package com.bank.spark.model;

// A join: both side sizes and how big the smaller side becomes in memory.
public class JoinCandidate {
    private final String name;
    private final long leftBytes;
    private final long rightBytes;
    private final double deserializationFactor; // in-memory expansion multiplier

    public JoinCandidate(String name, long leftBytes, long rightBytes, double deserializationFactor) {
        this.name = name;
        this.leftBytes = leftBytes;
        this.rightBytes = rightBytes;
        this.deserializationFactor = deserializationFactor;
    }

    public String getName() { return name; }
    public long smallerSideBytes() { return Math.min(leftBytes, rightBytes); }
    public long smallerSideInMemory() {
        return (long) (smallerSideBytes() * deserializationFactor);
    }
}
