package com.bank.spark.service;

import com.bank.spark.model.JoinCandidate;

// Decides broadcast safety in ABSOLUTE terms, not relative size.
public class BroadcastSafetyChecker {

    private final long safeBroadcastBytes;  // comfortable fraction of executor memory

    public BroadcastSafetyChecker(long safeBroadcastBytes) {
        this.safeBroadcastBytes = safeBroadcastBytes;
    }

    public String check(JoinCandidate j) {
        long inMem = j.smallerSideInMemory();
        if (inMem <= safeBroadcastBytes) {
            return "SAFE to broadcast: smaller side ~" + mb(inMem) + " in memory, within safe budget " + mb(safeBroadcastBytes);
        }
        // Smaller side is still too big — broadcasting would risk OOM.
        return "DO NOT broadcast: smaller side is " + mb(inMem)
                + " in memory (> safe " + mb(safeBroadcastBytes) + ") — use Sort Merge Join. 'smaller != safe'";
    }

    private String mb(long bytes) { return (bytes / (1024 * 1024)) + " MB"; }
}
