package com.bank.spark;

import com.bank.spark.model.JoinCandidate;
import com.bank.spark.service.BroadcastSafetyChecker;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BroadcastSafetyDemo {

    private static final Logger log = Logger.getLogger(BroadcastSafetyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Safe budget: ~200 MB of executor memory for a broadcast.
        BroadcastSafetyChecker checker = new BroadcastSafetyChecker(200L * 1024 * 1024);

        List<JoinCandidate> joins = List.of(
                // Tiny branch dim vs huge transactions — truly small → safe.
                new JoinCandidate("transactions ⋈ branches", 50_000_000_000L, 2L * 1024 * 1024, 3.0),
                // accounts is "smaller" but still 8 GB → NOT safe.
                new JoinCandidate("transactions ⋈ accounts", 50_000_000_000L, 8L * 1024 * 1024 * 1024, 3.0),
                // both huge → NOT safe.
                new JoinCandidate("transactions ⋈ positions", 50_000_000_000L, 20_000_000_000L, 3.0)
        );

        for (JoinCandidate j : joins) {
            String result = checker.check(j);
            if (result.startsWith("SAFE")) {
                log.info("[" + j.getName() + "] " + result);
            } else {
                log.warning("[" + j.getName() + "] " + result);
            }
        }

        log.warning("Rule: ask 'does it fit in executor memory', NOT 'is it the smaller side'.");
    }
}

